bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 - <<'PY'
import subprocess,json,sys,pathlib
def run(a,timeout=20):
 p=subprocess.run(a,capture_output=True,text=True,timeout=timeout)
 if p.returncode:raise RuntimeError("READ_FAILED_"+a[0])
 return p.stdout.strip()
files=[str(x) for x in pathlib.Path("deploy").rglob("*") if x.is_file() and ("gaybbs" in x.name.lower() or "compose" in x.name.lower())][:45]
source=run(["git","status","--porcelain"]).splitlines()
probe=run(["docker","exec","deploy-gaybbs-1","node","-e","const fs=require('fs');const s=fs.readFileSync('/app/gaybbs.mjs','utf8');console.log(JSON.stringify({has_startless:s.includes('gdm:'),has_search_restart_text:s.includes('Botの /start から共通メニュー'),has_video_specialist_guard:s.includes('VIDEO_SPECIALIST_ENTRY_TOPIC_IDS'),has_public_button_adapter:s.includes('publicNavigationButton')}))"])
inspect=run(["docker","inspect","-f","{{json .Config.Labels}}","deploy-gaybbs-1"])
labels=json.loads(inspect)
safe_labels={k:v for k,v in labels.items() if k in ["com.docker.compose.project","com.docker.compose.service","com.docker.compose.project.working_dir","com.docker.compose.project.config_files"]}
obj={"deploy_files":files,"dirty_count":len(source),"dirty_sample":[x[3:] for x in source[:25]],"running_runtime":json.loads(probe),"compose_labels":safe_labels}
body="STARTLESS_LIVE_DIAGNOSTIC="+json.dumps(obj,ensure_ascii=False,separators=(",",":"))
p=subprocess.run(["gh","api","repos/seigo-gace/GateApp-Bot/issues/68/comments","-f","body="+body],capture_output=True,text=True,timeout=45)
if p.returncode:sys.exit(70)
print("LIVE_STARTLESS_AND_DEPLOY_PATH_DIAGNOSTIC=PASS")
PY
